describe("extraUnsealPasswords", () => {
  const newPassword = "nova-senha-nova-senha-nova-senha-nova-senha";
  const oldPassword = "antiga-senha-antiga-senha-antiga-senha-antiga";
  const oldPassword2 = "antiga2-senha-antiga2-senha-antiga2-senha-antiga2";
  const otherPassword = "outra-senha-outra-senha-outra-senha-outra-senha";
  const legacyOptions = {
    ...sealDefaults,
    encryption: { ...sealDefaults.encryption, iterations: 1 },
    integrity: { ...sealDefaults.integrity, iterations: 1 },
  };

  const rotated = (extra: SessionConfig["extraUnsealPasswords"], rest?: Partial<SessionConfig>) =>
    ({
      name: "h3-rot",
      password: newPassword,
      extraUnsealPasswords: extra,
      ...rest,
    }) as SessionConfig;

  const sealWith = (
    password: string,
    options: typeof sealDefaults = sealDefaults,
    data: Record<string, any> = { foo: "bar" },
  ) => seal({ id: "rot", createdAt: Date.now(), data }, password, options);

  const setup = (config: SessionConfig, path: string) => {
    t.app.all(path, async (event) => {
      const session = await useSession(event, config);
      return { session };
    });
  };

  const sealedFrom = (res: Response) => {
    const setCookies = res.headers.getSetCookie();
    expect(setCookies).toHaveLength(1);
    return decodeURIComponent(setCookies[0].match(/h3-rot=([^;]+)/)![1]);
  };

  it("seals with password only", async () => {
    setup(rotated([oldPassword]), "/rot-seal");
    const res = await t.fetch("/rot-seal");
    const sealed = sealedFrom(res);
    expect(await unseal(sealed, newPassword, sealDefaults)).toMatchObject({ id: expect.any(String) });
    await expect(unseal(sealed, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("preserves sessions sealed with an extra password", async () => {
    setup(rotated([oldPassword]), "/rot-extra");
    const res = await t.fetch("/rot-extra", {
      headers: { Cookie: `h3-rot=${await sealWith(oldPassword)}` },
    });
    expect(await res.json()).toMatchObject({ session: { id: "rot", data: { foo: "bar" } } });
  });

  it("rejects sessions sealed with an unknown password", async () => {
    setup(rotated([oldPassword]), "/rot-unknown");
    const res = await t.fetch("/rot-unknown", {
      headers: { Cookie: `h3-rot=${await sealWith(otherPassword)}` },
    });
    const body = await res.json();
    expect(body.session.id).not.toBe("rot");
    expect(body.session.data).toEqual({});
  });

  it("does not retry extra passwords for non-password errors", async () => {
    setup(rotated([oldPassword, oldPassword2]), "/rot-expired");
    const expired = await sealWith(oldPassword, { ...sealDefaults, ttl: 1 });
    await new Promise((r) => setTimeout(r, 20));
    const spy = vi.spyOn(crypto.subtle, "deriveBits");
    try {
      const res = await t.fetch("/rot-expired", { headers: { Cookie: `h3-rot=${expired}` } });
      const body = await res.json();
      expect(body.session.id).not.toBe("rot");
      expect(spy).not.toHaveBeenCalled();
    } finally {
      spy.mockRestore();
    }
  });

  it("reseals sessions opened with an extra password", async () => {
    setup(rotated([oldPassword]), "/rot-reseal");
    const res = await t.fetch("/rot-reseal", {
      headers: { Cookie: `h3-rot=${await sealWith(oldPassword)}` },
    });
    expect(await res.json()).toMatchObject({ session: { id: "rot" } });
    const resealed = sealedFrom(res);
    expect(await unseal(resealed, newPassword, sealDefaults)).toMatchObject({
      id: "rot",
      data: { foo: "bar" },
    });

    // After removing the old password the new cookie is still valid
    setup(rotated([]), "/rot-removed");
    const res2 = await t.fetch("/rot-removed", { headers: { Cookie: `h3-rot=${resealed}` } });
    expect(await res2.json()).toMatchObject({ session: { id: "rot", data: { foo: "bar" } } });
  });

  it("tries extra passwords in order", async () => {
    setup(rotated([oldPassword, oldPassword2]), "/rot-order");
    const res = await t.fetch("/rot-order", {
      headers: { Cookie: `h3-rot=${await sealWith(oldPassword2)}` },
    });
    expect(await res.json()).toMatchObject({ session: { id: "rot", data: { foo: "bar" } } });
  });

  it("accepts legacy seals of extra passwords and reseals them", async () => {
    setup(rotated([oldPassword]), "/rot-legacy");
    const res = await t.fetch("/rot-legacy", {
      headers: { Cookie: `h3-rot=${await sealWith(oldPassword, legacyOptions)}` },
    });
    expect(await res.json()).toMatchObject({ session: { id: "rot", data: { foo: "bar" } } });
    expect(await unseal(sealedFrom(res), newPassword, sealDefaults)).toMatchObject({
      id: "rot",
    });
  });

  it("rejects legacy seals of extra passwords with legacySealFallback: false", async () => {
    setup(rotated([oldPassword], { legacySealFallback: false }), "/rot-legacy-off");
    const res = await t.fetch("/rot-legacy-off", {
      headers: { Cookie: `h3-rot=${await sealWith(oldPassword, legacyOptions)}` },
    });
    const body = await res.json();
    expect(body.session.id).not.toBe("rot");
    expect(body.session.data).toEqual({});
  });

  it("accepts extra passwords from the session header without resealing", async () => {
    t.app.get("/rot-header", async (event) => {
      const session = await getSession(event, rotated([oldPassword]));
      return { session };
    });
    const res = await t.fetch("/rot-header", {
      headers: { "x-h3-rot-session": await sealWith(oldPassword) },
    });
    expect(await res.json()).toMatchObject({ session: { id: "rot", data: { foo: "bar" } } });
    expect(res.headers.getSetCookie()).toHaveLength(0);
  });

  it("behaves as before with an empty extraUnsealPasswords", async () => {
    setup(rotated([]), "/rot-empty");
    const res = await t.fetch("/rot-empty", {
      headers: { Cookie: `h3-rot=${await sealWith(oldPassword)}` },
    });
    const body = await res.json();
    expect(body.session.id).not.toBe("rot");
    expect(body.session.data).toEqual({});
  });
});

