for (const [index, password] of passwords.entries()) {
  try {
    unsealed = await unsealWithPassword(sealed, password, config, sealOptions);
    if (index > 0 && unsealed) {
      // Opened with an extra password: reseal with `password` (see `getSession`)
      (unsealed as any)[kLegacySeal] = true;
    }
    break;
  } catch (error) {
    if (index === 0) {
      firstError = error;
